```js
// Input:
function test() {
  for (var l = 0; i < 10; l++) {
  }
  console.log("test")
}

window.a = [function() {
  return test()
}]

// Output:
window.a=[function(){return function(){for(var n=0;i<10;n++);console.log("test")}()}];
// Expected:
window.a=[function(){for(var n=0;i<10;n++);console.log("test")}];
```

If you remove the for loop, the `console.log` gets inlined without the extra unnecessary function.

